function barsFrom(flat: number[]): CandleBar[] {
  const bars: CandleBar[] = [];
  for (let index = 0; index < flat.length; index += 4) {
    bars.push({ open: flat[index] as number, high: flat[index + 1] as number, low: flat[index + 2] as number, close: flat[index + 3] as number });
  }
  return bars;
}

function expectedSignal(code: string, index: number): number {
  const character = code[index];
  return character === "+" ? 100 : character === "-" ? -100 : 0;
}

describe("TA-Lib candle arithmetic, checked against the C library's output", () => {
  it("reproduces all thirteen signals on 300 candles TA-Lib itself evaluated", () => {
    const mismatches: string[] = [];
    const fired = new Map<string, number>(SINGLE_CANDLE_PATTERNS.map((pattern) => [pattern, 0]));
    TALIB_CASES.forEach(([flat, code], caseIndex) => {
      const evaluation = evaluateSingleCandlePatterns(barsFrom(flat));
      if (!evaluation) throw new Error("fixture has fewer than eleven bars");
      SINGLE_CANDLE_PATTERNS.forEach((pattern, index) => {
        const expected = expectedSignal(code, index);
        if (expected !== 0) fired.set(pattern, (fired.get(pattern) ?? 0) + 1);
        if (evaluation.signals[pattern] !== expected) mismatches.push(`case ${caseIndex} ${pattern}: got ${evaluation.signals[pattern]}, TA-Lib ${expected}`);
      });
    });
    expect(mismatches).toEqual([]);
    for (const pattern of SINGLE_CANDLE_PATTERNS) expect(fired.get(pattern) ?? 0, `${pattern} fires in the fixtures`).toBeGreaterThanOrEqual(15);
  });

  it("reads the same lookback TA-Lib reports: 10 for every one of the thirteen", () => {
    for (const pattern of SINGLE_CANDLE_PATTERNS) expect(patternLookback(pattern)).toBe(10);
  });

  it("needs eleven bars", () => {
    expect(evaluateSingleCandlePatterns(barsFrom([1, 2, 0, 1]))).toBeNull();
  });

  it("holds TA-Lib's default settings", () => {
    expect(CANDLE_SETTINGS.BodyDoji).toMatchObject({ rangeType: "highLow", averagePeriod: 10, factor: 0.1 });
    expect(CANDLE_SETTINGS.ShadowShort).toMatchObject({ rangeType: "shadows", averagePeriod: 10, factor: 1 });
    expect(CANDLE_SETTINGS.ShadowVeryLong).toMatchObject({ rangeType: "realBody", averagePeriod: 0, factor: 2 });
    expect(CANDLE_SETTINGS.Near).toMatchObject({ rangeType: "highLow", averagePeriod: 5, factor: 0.2 });
  });

  it("averages the shadows and halves them; ShadowLong stands on this bar's own body", () => {
    const trailing: CandleBar[] = Array.from({ length: 10 }, () => ({ open: 4, high: 10, low: 0, close: 6 }));
    const current: CandleBar = { open: 10, high: 30, low: 0, close: 18 };
    // trailing shadows: upper 4 + lower 4 = 8 per bar, so 1.0 x (80 / 10) / 2.
    expect(candleAverage("ShadowShort", trailing, current).value).toBe(4);
    expect(candleAverage("ShadowLong", trailing, current).value).toBe(8);
    expect(candleAverage("ShadowVeryLong", trailing, current).value).toBe(16);
    expect(candleAverage("BodyDoji", trailing, current).value).toBeCloseTo(1, 12);
  });
});

describe("the calculator's synthetic candle", () => {
  it("builds the candle the notebook drew: default sliders, in ticks", () => {
    const candle = buildCandle(DEFAULT_CALCULATOR);
    expect(candle.high - candle.low).toBe(40);
    expect(candle.close - candle.open).toBeCloseTo(1.6, 12);
    expect(candle.high - Math.max(candle.open, candle.close)).toBeCloseTo(18, 12);
  });

  it("changes what fires while the candle stands still: only the ten bars behind it move", () => {
    const quiet = { ...DEFAULT_CALCULATOR, trailingRangeTicks: 4 };
    const wild = { ...DEFAULT_CALCULATOR, trailingRangeTicks: 200 };
    const candle = buildCandle(DEFAULT_CALCULATOR);
    const fire = (spec: typeof quiet) => {
      const evaluation = evaluateSingleCandlePatterns([...buildTrailingBars(spec), buildCandle(spec)]);
      return SINGLE_CANDLE_PATTERNS.filter((pattern) => evaluation?.signals[pattern] !== 0);
    };
    expect(buildCandle(quiet)).toEqual(candle);
    expect(buildCandle(wild)).toEqual(candle);
    expect(fire(quiet)).not.toContain("doji");
    expect(fire(wild)).toContain("doji");
    expect(fire(quiet)).not.toEqual(fire(wild));
  });

  const NOTEBOOK_STATES: Array<{ spec: [number, number, number, number]; fired: string[] }> = [
    { spec: [0.04, 0.45, 40, 40], fired: ["doji", "longleggeddoji", "rickshawman"] },
    { spec: [0.04, 0.45, 40, 4], fired: [] },
    { spec: [0.04, 0.45, 40, 200], fired: ["doji", "dragonflydoji", "highwave", "longleggeddoji", "rickshawman", "shortline", "spinningtop", "takuri"] },
    { spec: [0.8, 0.05, 60, 20], fired: ["longline"] },
    { spec: [-0.7, 0.1, 30, 30], fired: [] },
    { spec: [0.0, 0.5, 50, 50], fired: ["doji", "highwave", "longleggeddoji", "rickshawman", "spinningtop"] },
    { spec: [0.3, 0.3, 80, 40], fired: [] },
    { spec: [-0.02, 0.05, 120, 100], fired: ["belthold", "doji", "dragonflydoji", "longleggeddoji", "takuri"] },
    { spec: [0.15, 0.4, 25, 25], fired: [] },
  ];

  it("keeps the notebook's shortcut as the notebook ran it (nine slider states, outputs from its own cell)", () => {
    for (const { spec, fired } of NOTEBOOK_STATES) {
      const [bodyFraction, upperFraction, candleRangeTicks, trailingRangeTicks] = spec;
      expect(notebookApproximation({ bodyFraction, upperFraction, candleRangeTicks, trailingRangeTicks, trailingBodyFraction: null })).toEqual(fired);
    }
  });

  it("differs from TA-Lib's arithmetic where the shortcut halves the trailing range: longline at 0.8 / 0.05 / 60 / 20", () => {
    const spec = { bodyFraction: 0.8, upperFraction: 0.05, candleRangeTicks: 60, trailingRangeTicks: 20, trailingBodyFraction: null };
    expect(notebookApproximation(spec)).toContain("longline");
    // The ten bars' shadows total 4 ticks, so the short-shadow yardstick is 2, not 10: neither of this candle's 3 and 9 is short.
    const evaluation = evaluateSingleCandlePatterns([...buildTrailingBars(spec), buildCandle(spec)]);
    expect(evaluation?.averages.ShadowShort.value).toBeCloseTo(2, 12);
    expect(evaluation?.signals.longline).toBe(0);
  });
});

function studyRow(model: string, pattern: string, featureSet: string, balanced: number, seconds = 1): StudyRow {
  return {
    model_name: model, pattern_name: pattern, feature_set: featureSet, feature_count: 5, accuracy: balanced, balanced_accuracy: balanced,
    precision: balanced, recall: balanced, f1_score: balanced, area_under_curve: balanced, average_precision: balanced, prevalence: 0.1,
    positive_count: 10, train_positive_count: 20, train_bar_count: 100, test_bar_count: 50, training_seconds: seconds, recipe: "r",
  };
}

const ALONE = "single_bar_shape_only";
const CONTEXT = "single_bar_plus_trailing_context";
const ROWS: StudyRow[] = [
  studyRow("tree", "doji", ALONE, 0.9), studyRow("boost", "doji", ALONE, 0.95), studyRow("tree", "doji", CONTEXT, 0.99), studyRow("boost", "doji", CONTEXT, 1),
  studyRow("tree", "shortline", ALONE, 0.5), studyRow("boost", "shortline", ALONE, 0.6), studyRow("tree", "shortline", CONTEXT, 0.97), studyRow("boost", "shortline", CONTEXT, 0.98, 3),
];

describe("the study table's summaries", () => {
  it("takes the best model per pattern and feature set, then the gap the context is worth", () => {
    const best = bestPerPattern(ROWS, "balanced_accuracy");
    expect(best.map((row) => row.pattern)).toEqual(["doji", "shortline"]);
    expect(best[0]).toMatchObject({ alone: 0.95, context: 1 });
    expect(best[0]?.gap).toBeCloseTo(0.05, 12);
    expect(best[1]).toMatchObject({ alone: 0.6, context: 0.98 });
    expect(best[1]?.gap).toBeCloseTo(0.38, 12);
    expect(sortPatternBest(best, true).map((row) => row.pattern)).toEqual(["shortline", "doji"]);
    expect(sortPatternBest(best, false).map((row) => row.pattern)).toEqual(["doji", "shortline"]);
    const summary = summariseContext(best);
    expect(summary.aloneMean).toBeCloseTo(0.775, 12);
    expect(summary.contextMean).toBeCloseTo(0.99, 12);
    expect(summary.hardest).toEqual({ pattern: "shortline", alone: 0.6 });
  });

  it("ranks (model, feature set) by mean metric and names the context winner and runner-up", () => {
    const board = leaderboard(ROWS, "balanced_accuracy");
    expect(board[0]).toMatchObject({ model: "boost", featureSet: CONTEXT });
    expect(board[0]?.meanMetric).toBeCloseTo(0.99, 12);
    expect(board[0]?.meanSeconds).toBeCloseTo(2, 12);
    const { winner, runnerUp } = contextWinners(board);
    expect(winner?.model).toBe("boost");
    expect(runnerUp?.model).toBe("tree");
  });
});

describe("the notebook's eight numbers", () => {
  it("matches numpy: ddof 1 deviation, mean(z^3) skewness, mean(z^4) - 3 kurtosis, linear percentiles", () => {
    const summary = notebookEightNumbers([1, 2, 3, 4, 10]);
    expect(summary).toMatchObject({ count: 5, mean: 4, median: 3, percentile25: 2, percentile75: 4, minimum: 1, maximum: 10 });
    expect(summary?.standardDeviation).toBeCloseTo(3.5355339059327378, 12);
    expect(summary?.skewness).toBeCloseTo(0.8145870119269027, 12);
    expect(summary?.excessKurtosis).toBeCloseTo(-1.21568, 12);
    const second = notebookEightNumbers([0, 1, 5, 5, 9, 30]);
    expect(second?.standardDeviation).toBeCloseTo(11.093541664710447, 12);
    expect(second?.skewness).toBeCloseTo(1.1138956922882535, 12);
    expect(second?.excessKurtosis).toBeCloseTo(-0.4872490352286789, 12);
    expect(second?.percentile75).toBeCloseTo(8, 12);
  });

  it("gives null shape numbers for a constant or a too-short column, never a zero", () => {
    expect(notebookEightNumbers([2.5, 2.5, 2.5, 2.5])).toMatchObject({ skewness: null, excessKurtosis: null, standardDeviation: 0 });
    expect(notebookEightNumbers([1, 2, 3])).toMatchObject({ skewness: null, excessKurtosis: null });
    expect(notebookEightNumbers([])).toBeNull();
  });
});

describe("the study handler", () => {
  function contextWith(views: string[], rows: (sql: string) => unknown[]): { context: StudyContext; sql: string[] } {
    const sql: string[] = [];
    const lake: StudyLake = {
      async query<T>(text: string): Promise<T[]> {
        sql.push(text);
        return rows(text) as T[];
      },
      async hasView(name) {
        return views.includes(name);
      },
      async columns() {
        return [];
      },
    };
    return { context: { lake, notes: [] }, sql };
  }

  it("serves the study table, ordered, and lists the six views it reads", async () => {
    const { context, sql } = contextWith([STUDY_VIEW], () => ROWS);
    const body = await handler.run(handler.query.parse({}), context);
    expect(body.rows).toHaveLength(ROWS.length);
    expect(body.real).toBeNull();
    expect(sql[0]).toContain(`"${STUDY_VIEW}"`);
    expect(sql[0]).toContain("ORDER BY feature_set, model_name, pattern_name");
    expect(handler.datasets).toEqual([STUDY_VIEW, ...["1m", "5m", "15m", "1h", "4h"].map((timeframe) => `derived_mnq_next_candles_${timeframe}`)]);
  });

  it("answers an unlanded study table with a note and no rows", async () => {
    const { context } = contextWith([], () => ROWS);
    const body = await handler.run(handler.query.parse({}), context);
    expect(body).toEqual({ rows: [], real: null });
    expect(context.notes[0]).toContain(STUDY_VIEW);
  });

  it("refuses a pattern outside the thirteen before any SQL is built", () => {
    expect(handler.query.safeParse({ candlePattern: "hammer" }).success).toBe(false);
    expect(handler.query.safeParse({ candlePattern: 'doji"; DROP' }).success).toBe(false);
    expect(handler.query.safeParse({ candleTimeframe: "2m" }).success).toBe(false);
    expect(handler.query.parse({ candlePattern: "doji" })).toEqual({ candlePattern: "doji", candleTimeframe: "5m", candleIndex: 0 });
  });

  it("builds the real-candle read over one pattern column, numbered within each contract", () => {
    const sql = realCandleSql("derived_mnq_next_candles_5m", "doji", 7);
    expect(sql).toContain('"candlestick_doji" AS signal');
    expect(sql).toContain("PARTITION BY contract_symbol ORDER BY timestamp");
    expect(sql).toContain("LEAST(7, t.fired_count - 1)");
    expect(sql).toContain("position > 20");
    for (const name of SINGLE_CANDLE_PATTERNS) expect(sql).toContain(`"candlestick_${name}" AS "stored_${name}"`);
    expect(() => realCandleSql("derived_mnq_next_candles_5m", "doji; --", 0)).toThrow();
  });

  it("returns eleven bars with the firing last, and a note when there are fewer", async () => {
    const eleven = Array.from({ length: 11 }, (_, index) => ({
      timestamp_milliseconds: 1_700_000_000_000 + index * 300_000, contract_symbol: "MNQM4", sample_split: "train",
      open: 100 + index, high: 105 + index, low: 99 + index, close: 101 + index, stored_doji: index === 10 ? 100 : 0, stored_belthold: null,
      fired_index: 3, fired_count: 50,
    }));
    const full = contextWith(["derived_mnq_next_candles_5m"], () => eleven);
    const body = await handler.run(handler.query.parse({ candlePattern: "doji", candleIndex: 3 }), full.context);
    expect(body.rows).toEqual([]);
    expect(body.real).toMatchObject({ pattern: "doji", timeframe: "5m", contractSymbol: "MNQM4", firedIndex: 3, firedCount: 50 });
    expect(body.real?.bars).toHaveLength(11);
    expect(body.real?.bars[10]?.stored.doji).toBe(100);
    expect(body.real?.bars[10]?.stored.belthold).toBeNull();
    expect(body.real?.bars[0]?.stored.doji).toBe(0);

    const short = contextWith(["derived_mnq_next_candles_5m"], () => eleven.slice(4));
    const none = await handler.run(handler.query.parse({ candlePattern: "doji" }), short.context);
    expect(none.real).toBeNull();
    expect(short.context.notes[0]).toContain("doji");

    const absent = contextWith([], () => eleven);
    const missing = await handler.run(handler.query.parse({ candlePattern: "doji", candleTimeframe: "1h" }), absent.context);
    expect(missing.real).toBeNull();
    expect(absent.context.notes[0]).toContain("derived_mnq_next_candles_1h");
  });
});
